DROP TABLE IF EXISTS `booking_creative_slots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking_creative_slots` (
  `booking_creative_slot_id` int NOT NULL AUTO_INCREMENT,
  `booking_id` int NOT NULL,
  `creative_user_id` int NOT NULL,
  `role_id` int DEFAULT NULL,
  `event_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `expires_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`booking_creative_slot_id`),
  KEY `idx_bcs_creative_date` (`creative_user_id`,`event_date`) USING BTREE,
  KEY `idx_bcs_booking` (`booking_id`) USING BTREE,
  KEY `idx_bcs_status` (`status`) USING BTREE,
  KEY `idx_creative_slots_booking_active` (`booking_id`,`status`,`is_active`,`expires_at`),
  KEY `idx_creative_slots_booking_role` (`booking_id`,`role_id`,`status`,`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=155 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

