  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `rate` decimal(10,2) NOT NULL,
  `rate_type` enum('flat','per_hour','per_day','per_unit') NOT NULL DEFAULT 'flat',
  `rate_unit` varchar(50) DEFAULT NULL COMMENT 'e.g., "per video", "per hour", "25 photos"',
  `description` text,
  `min_quantity` int DEFAULT '0',
  `max_quantity` int DEFAULT NULL,
  `display_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `unique_item_slug` (`slug`,`pricing_mode`),
  KEY `idx_pricing_items_category` (`category_id`),
  KEY `idx_pricing_items_mode` (`pricing_mode`),
  KEY `idx_pricing_items_active` (`is_active`),
  CONSTRAINT `pricing_items_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `pricing_categories` (`category_id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
