--
-- Table structure for table `quotes`
--

DROP TABLE IF EXISTS `quotes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quotes` (
  `quote_id` int NOT NULL AUTO_INCREMENT,
  `booking_id` int DEFAULT NULL COMMENT 'FK to stream_project_booking if linked',
  `user_id` int DEFAULT NULL,
  `guest_email` varchar(255) DEFAULT NULL,
  `pricing_mode` enum('general','wedding') NOT NULL DEFAULT 'general',
  `shoot_hours` decimal(4,1) NOT NULL DEFAULT '0.0',
  `subtotal` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount_percent` decimal(5,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `price_after_discount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `margin_percent` decimal(5,2) NOT NULL DEFAULT '25.00',
  `margin_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `status` enum('draft','pending','confirmed','expired','cancelled') NOT NULL DEFAULT 'draft',
  `expires_at` timestamp NULL DEFAULT NULL,
  `notes` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `discount_code_id` int DEFAULT NULL,
  `applied_discount_type` enum('percentage','fixed_amount') DEFAULT NULL,
  `applied_discount_value` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`quote_id`),
  KEY `idx_quotes_booking` (`booking_id`),
  KEY `idx_quotes_user` (`user_id`),
  KEY `idx_quotes_status` (`status`),
  KEY `idx_discount_code` (`discount_code_id`),
  CONSTRAINT `fk_quotes_discount_code` FOREIGN KEY (`discount_code_id`) REFERENCES `discount_codes` (`discount_code_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

