--
-- Table structure for table `referrals`
--

DROP TABLE IF EXISTS `referrals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `referrals` (
  `referral_id` int NOT NULL AUTO_INCREMENT,
  `affiliate_id` int NOT NULL COMMENT 'FK to affiliates - the referrer',
  `payment_id` int DEFAULT NULL COMMENT 'FK to payment_transactions - the booking payment',
  `referral_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'The referral code used',
  `referred_user_id` int DEFAULT NULL COMMENT 'FK to users - the referred customer (null for guests)',
  `referred_guest_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Guest email if not a registered user',
  `booking_amount` decimal(10,2) DEFAULT NULL COMMENT 'Total booking amount',
  `commission_amount` decimal(10,2) NOT NULL DEFAULT '200.00' COMMENT 'Fixed commission per booking (200 SAR)',
  `status` enum('pending','completed','cancelled','refunded') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'Referral status',
  `payout_status` enum('pending','approved','paid','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'Payout status for this referral',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Admin notes',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`referral_id`),
  KEY `referred_user_id` (`referred_user_id`),
  KEY `idx_affiliate_id` (`affiliate_id`),
  KEY `idx_payment_id` (`payment_id`),
  KEY `idx_referral_code` (`referral_code`),
  KEY `idx_status` (`status`),
  KEY `idx_payout_status` (`payout_status`),
  KEY `idx_created_at` (`created_at`),
