DROP TABLE IF EXISTS `streams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `streams` (
  `stream_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_by_user_id` int DEFAULT NULL,
  `stream_project_booking_id` int DEFAULT NULL,
  `ivs_channel_arn` varchar(255) NOT NULL,
  `ivs_playback_url` text NOT NULL,
  `ivs_stream_key_arn` varchar(255) NOT NULL,
  `ivs_stream_key_enc` text,
  `ivs_ingest_endpoint` varchar(255) DEFAULT NULL,
  `medialive_input_id` varchar(100) DEFAULT NULL,
  `medialive_channel_id` varchar(100) DEFAULT NULL,
  `status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0=CREATED,1=READY,2=LIVE,3=STOPPED,4=ENDED',
  `started_at` datetime DEFAULT NULL,
  `ended_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `recording_enabled` tinyint(1) DEFAULT '0',
  `recording_s3_prefix` varchar(255) DEFAULT NULL,
  `replay_url` varchar(512) DEFAULT NULL,
  `recording_status` tinyint NOT NULL DEFAULT '0' COMMENT '0 = disabled, 1 = recording, 2 = processing, 3 = ready',
  PRIMARY KEY (`stream_id`),
  KEY `idx_status` (`status`),
  KEY `idx_spb` (`stream_project_booking_id`),
  KEY `idx_created_by` (`created_by_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
